UPDATE weekly_plan
SET note = #{note}, version = version + 1
WHERE id = #{id} AND version = #{version}

UPDATE weekly_plan_item
SET planned_amount = #{plannedAmount}
WHERE weekly_plan_id = #{weeklyPlanId} AND task_id = #{taskId}

